/* ==== INTERFACE ====
方向：Bento Grid (便当盒布局)。现代清爽的模块化排版，浅灰蓝底色搭配高对比无衬线字体；利用精细微圆角模块边界、功能分区与图解流线，清晰呈现单个神经元结构、前向反向传播流动及二维决策面训练与过拟合对比。
reference: style:05-bento-grid
token --bg：页面底色 #f4f6f9。
token --text：正文色 #111827。
token --font-sans：正文与控件字体栈 "NTF-inter", "NTF-noto-sans-sc", sans-serif。
token --font-display：标题字体栈 "NTF-space-grotesk", "NTF-noto-sans-sc", sans-serif。
token --primary：重点蓝 #2563eb。
token --primary-soft：浅蓝背景 #dbeafe。
token --accent-orange：梯度/损失高亮暖橙 #ea580c。
token --accent-purple：激活/非线性紫色 #7c3aed。
token --success：良好泛化/收敛翠绿 #059669。
token --danger：过拟合/高损失玫瑰红 #e11d48。
token --border-subtle：精细模块边界线 #e2e8f0。
token --muted：次要说明字色 #64748b。
字阶：
--fs-h1: 40px / 1.25 (普通页题名)
--fs-h2: 24px / 1.35 (区块标题/模块大字)
--fs-lead: 20px / 1.45 (导引段落)
--fs-body: 16px / 1.55 (正文字号，行高适读)
--fs-sec: 14px / 1.45 (二级辅助文字、图解旁白)
--fs-label: 13px / 1.2 (标签、参数提示、徽章)
--fs-tick: 12px / 1.0 (图表坐标数字刻度)
class .nt-title：普通页题名，英文 Space Grotesk 700 + 中文 Noto Sans SC 700，40px/1.25。
class .nt-section-title：模块标题，24px/1.35，半粗体 600。
class .nt-bento-cell：便当盒单元容器外观，白底(#ffffff)、柔和阴影、16px圆角与细边框。
class .nt-badge：模块顶端或图解中的轻量类别标签/药丸徽章。
class .nt-controls：通用操作栏外观（按钮、步进器、切页滑块）。
class .nt-flow-arrow：前向/反向传播流动指示线（支持 data-direction="forward|backward"）。
class .nt-metric-callout：数据指标高亮卡，大数字展示损失值、轮数(Epoch)、准确率。
variant opening：封面模式，更强烈的中心大标题层级(--fs-cover: 54px)，带微妙的浅色神经元连接网格底纹。
默认：不设 data-variant；干净平滑的浅灰冷调基底，无图时完全可用。
品牌：无全局 logo。
==== /INTERFACE ==== */

/* ---------------- 字体声明 ---------------- */
@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-space-grotesk";
  src: url("fonts/library/space-grotesk/face-0.ttf");
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

/* ---------------- 全局根变量 ---------------- */
:root {
  --bg: #f4f6f9;
  --bg-gradient: radial-gradient(circle at 85% 15%, #e9effd 0%, #f4f6f9 60%);
  --text: #111827;
  --muted: #64748b;
  --border-subtle: #e2e8f0;
  --border-focus: #94a3b8;

  /* 主题强调色：用于神经元流向、图表曲线、决策面分类 */
  --primary: #2563eb;
  --primary-soft: #eff6ff;
  --primary-border: #bfdbfe;

  --accent-orange: #ea580c;
  --accent-orange-soft: #fff7ed;

  --accent-purple: #7c3aed;
  --accent-purple-soft: #f5f3ff;

  --success: #059669;
  --success-soft: #ecfdf5;

  --danger: #e11d48;
  --danger-soft: #fff1f2;

  --focus: #2563eb;

  /* 字体栈 */
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-display: "NTF-space-grotesk", "NTF-noto-sans-sc", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;

  /* 字阶 (逻辑像素) */
  --fs-cover: 52px;
  --fs-h1: 38px;
  --fs-h2: 24px;
  --fs-h3: 18px;
  --fs-lead: 20px;
  --fs-body: 16px;
  --fs-sec: 14px;
  --fs-label: 13px;
  --fs-tick: 12px;

  /* 共享圆角与微阴影 */
  --radius-bento: 20px;
  --radius-sub: 12px;
  --radius-badge: 9999px;
  --shadow-bento: 0 4px 20px -2px rgba(15, 23, 42, 0.05), 0 1px 3px 0 rgba(15, 23, 42, 0.03);
  --shadow-bento-hover: 0 10px 25px -3px rgba(15, 23, 42, 0.08), 0 4px 6px -2px rgba(15, 23, 42, 0.04);
}

/* ---------------- 舞台背景 ---------------- */
#stage {
  background-color: var(--bg);
  background-image: 
    radial-gradient(#cbd5e1 1px, transparent 1px),
    var(--bg-gradient);
  background-size: 28px 28px, 100% 100%;
  background-position: 0 0, 0 0;
  background-repeat: repeat, no-repeat;
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* 封面变体 */
html[data-variant="opening"] #stage {
  background-image: 
    radial-gradient(#93c5fd 1.2px, transparent 1.2px),
    radial-gradient(circle at 50% 20%, #e0e7ff 0%, #f4f6f9 70%);
  background-size: 32px 32px, 100% 100%;
}

/* ---------------- 标题排版 ---------------- */
.nt-title {
  font-family: var(--font-display);
  font-size: var(--fs-h1);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.02em;
  color: var(--text);
  margin: 0;
}

.nt-title:lang(zh) {
  letter-spacing: -0.01em;
}

html[data-variant="opening"] .nt-title {
  font-size: var(--fs-cover);
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.nt-section-title {
  font-family: var(--font-display);
  font-size: var(--fs-h2);
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: -0.015em;
  color: var(--text);
  margin: 0;
}

.nt-lead {
  font-size: var(--fs-lead);
  line-height: 1.5;
  color: var(--muted);
  margin: 0;
}

.nt-body {
  font-size: var(--fs-body);
  line-height: 1.6;
  color: var(--text);
  margin: 0;
}

.nt-caption {
  font-size: var(--fs-sec);
  line-height: 1.5;
  color: var(--muted);
}

/* ---------------- 便当盒卡片单元 (Bento Cell) ---------------- */
.nt-bento-cell {
  background: #ffffff;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-bento);
  box-shadow: var(--shadow-bento);
  box-sizing: border-box;
  padding: 24px;
  position: relative;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.nt-bento-cell.interactive:hover {
  box-shadow: var(--shadow-bento-hover);
  transform: translateY(-2px);
}

/* 高亮/强调色调边框的 Bento Cell */
.nt-bento-cell[data-tone="primary"] {
  border-color: var(--primary-border);
  background: linear-gradient(180deg, #ffffff 0%, var(--primary-soft) 100%);
}

.nt-bento-cell[data-tone="accent"] {
  border-color: #fed7aa;
  background: linear-gradient(180deg, #ffffff 0%, var(--accent-orange-soft) 100%);
}

/* ---------------- 徽章标签 (Badge / Tag) ---------------- */
.nt-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  font-size: var(--fs-label);
  font-weight: 500;
  line-height: 1.2;
  border-radius: var(--radius-badge);
  background: #f1f5f9;
  color: #475569;
  border: 1px solid #e2e8f0;
}

.nt-badge[data-color="primary"] {
  background: var(--primary-soft);
  color: var(--primary);
  border-color: var(--primary-border);
}

.nt-badge[data-color="orange"] {
  background: var(--accent-orange-soft);
  color: var(--accent-orange);
  border-color: #fed7aa;
}

.nt-badge[data-color="purple"] {
  background: var(--accent-purple-soft);
  color: var(--accent-purple);
  border-color: #ddd6fe;
}

.nt-badge[data-color="success"] {
  background: var(--success-soft);
  color: var(--success);
  border-color: #a7f3d0;
}

.nt-badge[data-color="danger"] {
  background: var(--danger-soft);
  color: var(--danger);
  border-color: #fecdd3;
}

/* ---------------- 指标提示卡 (Metric Callout) ---------------- */
.nt-metric-callout {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nt-metric-callout .val {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
}

.nt-metric-callout .lbl {
  font-size: var(--fs-sec);
  color: var(--muted);
  font-weight: 400;
}

/* ---------------- 交互控件栏 (Controls) ---------------- */
.nt-controls {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px;
  background: #ffffff;
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.nt-controls button,
.nt-btn {
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 500;
  line-height: 1.4;
  padding: 8px 16px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: #f1f5f9;
  color: #334155;
  cursor: pointer;
  transition: all 0.15s ease;
  outline: none;
}

.nt-controls button:hover,
.nt-btn:hover {
  background: #e2e8f0;
  color: #0f172a;
}

.nt-controls button:focus-visible,
.nt-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.nt-controls button.active,
.nt-controls button[aria-pressed="true"],
.nt-btn-primary {
  background: var(--primary);
  color: #ffffff;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.3);
}

.nt-controls button.active:hover,
.nt-btn-primary:hover {
  background: #1d4ed8;
}

/* ---------------- 神经计算图 / SVG 图解笔触 ---------------- */
svg .nt-edge {
  fill: none;
  stroke: #cbd5e1;
  stroke-width: 2px;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: stroke 0.2s, stroke-width 0.2s;
}

svg .nt-edge.forward {
  stroke: var(--primary);
}

svg .nt-edge.backward {
  stroke: var(--accent-orange);
  stroke-dasharray: 4 3;
}

svg .nt-edge.accent-purple {
  stroke: var(--accent-purple);
}

svg .nt-node {
  stroke: #ffffff;
  stroke-width: 3px;
  fill: var(--primary);
  transition: transform 0.2s ease, fill 0.2s ease;
}

svg .nt-node.input {
  fill: #64748b;
}

svg .nt-node.hidden {
  fill: var(--primary);
}

svg .nt-node.output {
  fill: var(--accent-purple);
}

svg .nt-node-text {
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 600;
  fill: #ffffff;
  text-anchor: middle;
  dominant-baseline: central;
  pointer-events: none;
}

/* 刻度与图表标签 */
.nt-chart-tick {
  font-family: var(--font-sans);
  font-size: var(--fs-tick);
  fill: var(--muted);
  color: var(--muted);
}

.nt-chart-label {
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 500;
  fill: var(--text);
  color: var(--text);
}

/* ---------------- 辅助代码块风格 ---------------- */
.nt-code-pill {
  font-family: var(--font-mono);
  font-size: 13px;
  padding: 2px 6px;
  border-radius: 6px;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  color: #0f172a;
}
